// KeyPairInput A signing key pair used for Debian, Alpine, RPM, Helm provenance and Terraform provider signing. Private material is write-only and stored as a sealed column (decision 0017).
type KeyPairInput struct {
	// Alias Required within this object. Alias embedded in the public key material and shown to package clients; not an identifier.
	Alias string `json:"alias"`

	// PairName Required within this object. Unique name of the pair; it is the identifier in every other key-pair operation and in a repository's primaryKeyPairRef and secondaryKeyPairRef fields.
	PairName string `json:"pairName"`

	// PairType Required within this object. RSA for Debian, Alpine and RPM signing, GPG for Helm provenance and Terraform provider registries.
	PairType KeyPairInputPairType `json:"pairType"`

	// Passphrase Optional within this object. Passphrase protecting privateKey, if any. Stored sealed and never returned.
	Passphrase *string `json:"passphrase,omitempty"`

	// PrivateKey Required within this object. PEM or ASCII-armored private key. Accepted on create, update and verify, never returned.
	PrivateKey *string `json:"privateKey,omitempty"`

	// PublicKey Required within this object. PEM or ASCII-armored public key. This is the only key material a read returns.
	PublicKey string `json:"publicKey"`

	// VaultKey Optional within this object. Name of an external vault key to use instead of privateKey. Accepted but not used; a pair that sets it without privateKey is rejected with 400.
	VaultKey *string `json:"vaultKey,omitempty"`

	// VaultPublicKey Optional within this object. Location of the public key in an external vault when vaultKey is used. Accepted and ignored.
	VaultPublicKey *struct {
		// Key Optional within this object. Field name inside the vault entry.
		Key *string `json:"key,omitempty"`

		// Path Optional within this object. Vault path holding the key.
		Path *string `json:"path,omitempty"`
	} `json:"vaultPublicKey,omitempty"`
}

// KeyPairInputPairType Required within this object. RSA for Debian, Alpine and RPM signing, GPG for Helm provenance and Terraform provider registries.
type KeyPairInputPairType string

// KeyPairSummary The readable projection of a key pair. Reads never include private material or the passphrase.
type KeyPairSummary struct {
	// Alias Optional within this object. Alias embedded in the key.
	Alias *string `json:"alias,omitempty"`

	// PairName Optional within this object. Pair name, the identifier.
	PairName *string `json:"pairName,omitempty"`

	// PairType Optional within this object. RSA or GPG.
	PairType *string `json:"pairType,omitempty"`

	// PublicKey Optional within this object. The public key material.
	PublicKey *string `json:"publicKey,omitempty"`
}

// LatestVersionByPropertiesResult The highest version found among items carrying a lowercase version property, and the items that carry it.
type LatestVersionByPropertiesResult struct {
	// Artifacts Optional within this object. The files that carry the winning version when listFiles=1; empty otherwise.
	Artifacts *[]struct {
		// Uri Optional within this object. Absolute download URL of the file.
		Uri *string `json:"uri,omitempty"`
	} `json:"artifacts,omitempty"`

	// Version Optional within this object. The winning version string, compared with Maven version ordering.
	Version *string `json:"version,omitempty"`
}

// LegacyTokenDetails One token in the legacy listing.
type LegacyTokenDetails struct {
	// Expiry Optional within this object. Expiry as Unix seconds; absent for non-expiring tokens.
	Expiry *int `json:"expiry,omitempty"`

	// IssuedAt Optional within this object. Issue time as Unix seconds.
	IssuedAt *int `json:"issued_at,omitempty"`

	// Issuer Optional within this object. Issuing service id, for example jfrt@ followed by the service id.
	Issuer *string `json:"issuer,omitempty"`

	// Refreshable Optional within this object. Whether a refresh token was issued.
	Refreshable *bool `json:"refreshable,omitempty"`

	// Subject Optional within this object. Subject in the form jfac@<id>/users/<name>.
	Subject *string `json:"subject,omitempty"`

	// TokenId Optional within this object. Identifier used to revoke the token.
	TokenId *string `json:"token_id,omitempty"`
}

// LegacyTokenList The legacy token listing.
type LegacyTokenList struct {
	// Tokens Optional within this object. Tokens visible to the caller; admins see all.
	Tokens *[]LegacyTokenDetails `json:"tokens,omitempty"`
}

// LegacyTokenResponse The legacy token create or refresh response. The same token is also visible through /access/api/v1/tokens.
type LegacyTokenResponse struct {
	// AccessToken Optional within this object. The JWT access token.
	AccessToken *string `json:"access_token,omitempty"`

	// ExpiresIn Optional within this object. Lifetime in seconds; 0 means the token never expires.
	ExpiresIn *int `json:"expires_in,omitempty"`

	// RefreshToken Optional within this object. Present only when refreshable was true.
	RefreshToken *string `json:"refresh_token,omitempty"`

	// Scope Optional within this object. The granted scope string.
	Scope *string `json:"scope,omitempty"`

	// TokenType Optional within this object. Always Bearer.
	TokenType *string `json:"token_type,omitempty"`
}

// License defines model for License.
